script:
export const meta = {
  name: 'W912-二轮-预审',
  description: 'W912 二轮（环7—12：版之鲜、取须见其亮、待入之账、图之自随、自入可裁、怀疑之验）：起稿入方案 → 二攻者预审 → 定 → 复攻其改 → 再定（⛔施）',
  phases: [
    { title: '稿', detail: '环7—12 入 W912.md' },
    { title: '预审', detail: '二攻者' },
    { title: '定', detail: '纳防' },
    { title: '复审', detail: '只攻所改' },
    { title: '再定', detail: '纳复审之防·审之指' },
  ],
}
const S = '/tmp/claude-0/-home-user/fc87a25e-bbf0-5a31-be3f-8a53382aa0f0'
const WT = S + '/scratchpad/wt912'
const PLAN = WT + '/设定/方案/W912.md'
const ENV = `
【境】施工之树：${WT}（HEAD 848ea9bf0＝W912 一轮已施已验而未入主、已并主枝〔含 W911 之预审之律、480 段案之正〕）。方案：${PLAN}（一轮之环1—6 已在）。二轮之稿：${S}/scratchpad/W912_二轮.md（环7—12 之表行）。
⛔git commit/push/checkout/stash/reset；⛔动 /home/user/the-novel 与他树；试於 /tmp 之副本（cp -a 或 git worktree add 於 /tmp 而毕即 git worktree remove），试毕必删。零 token 之器只读只跑。文风：仓之文风（简、文言之词）。
作者 1120 之令：「更新的……都要及时地去用上……及时地去替换掉老的版本……千万不要拖」「替换的时候……体系总图它会自动进行更新……不用刻意地去更新……连接成一个整体」「完完全全就是自动化的」。质之铁律：⛔伤书之质、⛔拖累写书；写书之路（席在跑吗、会话之守、链之检、推闸、封版、自走、承、.github/workflows）之改唯章界入；⛔绕平台之检（推.py --直 已被拒、⛔--no-verify）。坑65：方案之核心之断须经预审；坑61：唤隔之费（缓存一时之档）；坑53：同功两处。`
const RISKS = { type: 'object', properties: {
  risks: { type: 'array', description: 'risks', items: { type: 'object', properties: {
    risk: { type: 'string', description: '险' }, ring: { type: 'string', description: '环N 或 取' },
    evidence: { type: 'string', description: '据（档:行、实跑之令与其果）' }, defense: { type: 'string', description: '防（可施、有锚、⛔以否定起首）' } },
    required: ['risk', 'ring', 'evidence', 'defense'] } },
  verdict: { type: 'string', description: '判：可施／须改（由）' } }, required: ['risks', 'verdict'] }
const FIN = { type: 'object', properties: { adopted: { type: 'number', description: '纳' }, rejected: { type: 'number', description: '驳' }, changedRings: { type: 'string', description: '所改之环' }, gist: { type: 'string', description: '要' } }, required: ['adopted', 'rejected', 'changedRings', 'gist'] }

phase('稿')
const draft = await agent(`${ENV}
【汝之职】起稿：把二轮之稿之环7—12 并入 ${PLAN} 之「## 逐环」表（环号续一轮），每环之「确证」须亲核（读档:行、只读跑之令）——稿中之行号已旧者以今为准；「## 虫洞之择」末书恰一行「- 兜底之隔：不改」（二轮⛔改唤隔；若环涉巡之隔则书「改——缓存之算：冷$…暖$…日$…」）；「## 图之用」以 python3 工具/方案.py --图 W912 重出而贴（二轮新件俱入）；「## 合计」「## 坑之检」随之（坑53、坑㊱、坑63、坑65、坑61）；立「## 预审」之节：预审者「wf_待补」、审之指占位。只改此档。跑 python3 工具/方案.py --验 W912 书其果。返其要。`, { label: '稿:W912二轮', phase: '稿', schema: { type: 'object', properties: { gist: { type: 'string', description: '要' } }, required: ['gist'] } })

phase('预审')
const LENS = [
  { key: '自动之险', p: '环10 图之自随（推.py 自添随治之提交、巡之自愈於 ROOT 跑 --随治＋推.py）与环11 自入（施工流.js 之入：commit、并主枝、推）——会否越写书之路之界、会否在写书之坐在跑时动主枝、会否成无人之推而失控、⛔绕平台之检、提交之签与尾、并之冲突、自推之递归（随治之提交又触图旧）；环7③ 本坐之树自新（ff 之条件、不净与分叉）。' },
  { key: '判之真', p: '环7 版之鲜之判（blob 比、云巡与写坐之迹之版、旧心跳无键之 ⚪）、环8 取须见其亮（灯之稳、豁之滥、废件仍亮）、环9 待入之账（worktree 之读、误红：已入主而树未删、施工中之树）、环4「唯异方印」之静印⛔增本坐上下文；并以 W905—W911 之真史回放其判。' },
]
const atk1 = await parallel(LENS.map(l => () => agent(`${ENV}
【汝之职】预审之攻者（只读）——汝之眼：${l.key}。${l.p}
先读方案全文（二轮诸环），再读其所引之档与器以实证（可於 /tmp 副本实跑）。只报真险：每险有据、有可施之防。险至多 10 条；无真险即 risks 空、判「可施」。`, { label: `预审:${l.key}`, phase: '预审', schema: RISKS })))

phase('定')
const a1 = atk1.filter(Boolean)
const fin1 = await agent(`${ENV}
【汝之职】定：纳预审之防於 ${PLAN}（只改此档）。预审之果：${JSON.stringify(a1)}
逐险或纳（改其环之做什么、确证、败则）或驳（书由於「## 注」）。「## 预审」之节：每险一行「- 险（环N｜取）：…｜防：…」（防⛔以否定起首、须有锚）；判之行：有「须改」者「- 判：须改→已改 环…」。⛔填预审者与审之指（再定时填）。返所纳、所驳、所改之环。`, { label: '定:一', phase: '定', schema: FIN })

phase('复审')
const atk2 = await agent(`${ENV}
【汝之职】复审之攻者（只读）：只攻定稿所改之处（所改之环：${fin1 ? fin1.changedRings : '未知'}）——防是否真落、改与改相撞否、改後生新病否（尤以自动之推与写书之路之界）。先读预审之果 ${JSON.stringify(a1.map(a => a.verdict))} 与方案今文。险至多 6 条；无真险即 risks 空、判「可施」。`, { label: '复审:所改', phase: '复审', schema: RISKS })

phase('再定')
const fin2 = await agent(`${ENV}
【汝之职】再定：纳复审之防於 ${PLAN}（只改此档）。复审之果：${JSON.stringify(atk2)}
一、逐险纳或驳（同前）；复审之险亦各添一行於「## 预审」。二、预审者之行书「- 预审者：wf_待补（攻者 ${a1.length + (atk2 ? 1 : 0)}：预审 ${a1.length}、复审 1）」。三、判之行：列所改之环之并。四、跑 cd ${WT} && python3 工具/方案.py --预审之指 W912 以其所印填「- 审之指：」；再跑 python3 工具/方案.py --验 W912（唯「wf_待补」致之坏可许——书之）。返之。`, { label: '再定', phase: '再定', schema: FIN })
return { draft, atks: [...a1, ...(atk2 ? [atk2] : [])], fin1, fin2 }
